import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"root/README.md","filePath":"root/README.md"}'),r={name:"root/README.md"};function n(i,e,d,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<div align="center"><h1 id="open-cube-os" tabindex="-1">Open Cube OS <a class="header-anchor" href="#open-cube-os" aria-label="Permalink to &quot;Open Cube OS&quot;">​</a></h1><p><strong>A from-scratch x86_64 kernel that boots into ring 3.</strong></p><p>Current development preview: <strong>3.0.0-WP-l1apps-merge</strong> - the OCBL bootloader, a pure L0 service kernel (no shell, no TUI, no IME in L0), <strong>284 ring-3 programs</strong> under <code>ocos/l1apps/</code> - now organized around <strong>8 merged mega-apps</strong> (<code>update</code> / <code>disk-tool</code> / <code>net-tool</code> / <code>sound-tool</code> / <code>files</code> / <code>sysdiag</code> / <code>hwinfo</code> / <code>power</code>), each an intent wizard <em>and</em> a verbatim dispatch for every classic command underneath. Stable line: <strong>2.2.0</strong> (the last formal release of the 2.x world, kept for reference and real-hardware stability). See <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">Releases</a>.</p><p><code>ush&gt;</code> is the prompt. Everything is extensible.</p><p><a href="https://ocos.cubestudio.cn/" target="_blank" rel="noreferrer">Website</a> · <a href="https://ocos.cubestudio.cn/docs/" target="_blank" rel="noreferrer">Documentation</a> · <a href="#downloads">Downloads</a> · <a href="./BUILDING.html">Building</a> · <a href="./ARCHITECTURE.html">Architecture</a> · <a href="./INTERFACES.html">Interface Reference</a></p></div><hr><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Open Cube OS is <strong>L0 + L1</strong>:</p><ul><li><p><strong>L0 provides services.</strong> A pure service kernel - the boot chain, the core mechanisms, the drivers, the root services and the numbered interface. 3.0.0-WP03 deleted the L0 user plane entirely (the 2.x <code>oc&gt;</code> recovery shell, the in-kernel TUI, the input method engine); L0 finishes boot at <code>L0 ready, waiting for L1</code> and hands the machine to the default ring-3 entry.</p></li><li><p><strong>L1 uses services.</strong> 284 ring-3 programs under <code>ocos/l1apps/</code> (one command = one app = one folder): the default boot entry is the <code>ush</code> user shell (<strong>296 commands = 284 registry apps + 12 built-ins, zero commands in L0</strong>), the TUI desktop, the editor, the Chinese console + pinyin IME - and the 8 merged mega-apps that give the whole surface an intent-based front door: no-argument wizards with auto-detection and cross-domain repair (the <code>update</code> wizard fixes a missing IP through DHCP and a missing A/B disk through <code>abdisk</code> before it ever checks for updates), <code>direct</code> explicit passthrough, and classic verbatim dispatch with zero functionality loss.</p></li><li><p><strong>Not a Linux fork.</strong> 158,474 lines of original C/assembly across 764 files under Apache 2.0 (verify: see <em>Stats</em> below).</p></li><li><p><strong>Boots everywhere the PC platform goes:</strong> one hybrid BIOS + UEFI ISO through OCBL, the in-tree bootloader (512-byte real-mode stage 1 / EFI entry, 16→32→64-bit long mode, dynamic disk scan) - 512 MiB RAM is comfortable, disk optional.</p></li><li><p><strong>A real kernel:</strong> preemptive scheduler, 4-level paging, ring-3 user programs with 54 syscalls, VFS over FAT32/exFAT/ext4/ramfs, a full TCP/IP stack with TLS 1.2/1.3 and SSH (client <em>and</em> server), 15 driver families from NVMe to xHCI to ACPI AML, crash dumps, hardware watchdog (Intel TCO / ACPI WDAT), OTA A/B updates, and the WP07a boot-state monitor: six boot stages recorded into a fixed state area, per-phase watchdog budgets, and a post-mortem BOOT_FAILED record OCIRE reads after the reboot to print the stall point and repair advice.</p></li><li><p><strong>Honest by design:</strong> if the ring-3 world cannot start, L0 says so and halts - the guidance is a reboot or the OCBL boot menu (there is deliberately no L0 shell to fall back to).</p></li></ul><p>The two-layer architecture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  OCOS (ocos/)          kernel + drivers + root services + the</span></span>
<span class="line"><span>                          numbered L1SVC ABI - no shell, no TUI</span></span>
<span class="line"><span>L1  the world (ocos/l1apps/)  284 programs: ush, TUI, editor, IME,</span></span>
<span class="line"><span>                          one command per app, and the 8 merged</span></span>
<span class="line"><span>                          mega-apps (296 commands total)</span></span></code></pre></div><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What you get</th></tr></thead><tbody><tr><td>Boot</td><td>OCBL - the in-tree bootloader: hybrid BIOS + UEFI ISO, 16→32→64-bit long mode, dynamic disk scan, boot menu with a 10 s countdown (no GRUB in the 3.0.0 chain)</td></tr><tr><td>Memory</td><td>PMM bitmap over the boot memory map, 4-level VMM, kmalloc heap with real growth via #PF</td></tr><tr><td>CPU</td><td>Preemptive priority + round-robin scheduler, 256-gate IDT with IST stacks, 100 Hz PIT + HPET/PM-timer/TSC sources, LAPIC</td></tr><tr><td>Ring 3</td><td>ELF loader, 54 syscalls, signals, fork/exec/pipes/select/mmap, dynamic linking (in-tree ld.so, PIE, dlsym); SYS_L1SVC + SYS_NETCMD service bridges</td></tr><tr><td>Storage</td><td>AHCI, ATA/ATA-DMA, NVMe, virtio-blk, USB MSC, SCSI (LSI); FAT32 with LFN, exFAT, ext4, ramfs; GPT/MBR partitions; A/B slots</td></tr><tr><td>Network</td><td>e1000/e1000e/igb/ixgbe/rtl8139/rtl8169-family/BCM57xx drivers, ARP/IPv4/ICMP/UDP/DNS/TCP with congestion control, sockets, firewall, HTTPS client (TLS 1.2/1.3 + X.509 chains), SSH client + sshd</td></tr><tr><td>USB</td><td>UHCI, OHCI, EHCI, xHCI; mass storage, HID, serial, audio classes</td></tr><tr><td>Media</td><td>HDA / AC97 / SB16 / ES1370 / virtio sound; UVC cameras with MJPEG</td></tr><tr><td>Platform</td><td>ACPI (FADT/DSDT/MCFG, real AML walker, S3 suspend/resume), Intel TCO + ACPI WDAT hardware watchdogs, HPET, i2c/SMBus</td></tr><tr><td>Shell</td><td>ush (ring 3, the default boot entry): 284 registry apps + 12 built-ins with pipes/redirection/env/aliases/jobs; zero commands in L0</td></tr><tr><td>Mega-apps</td><td>The 8 merged apps (<code>update</code>, <code>disk-tool</code>, <code>net-tool</code>, <code>sound-tool</code>, <code>files</code>, <code>sysdiag</code>, <code>hwinfo</code>, <code>power</code>): intent wizards with cross-domain repair + <code>direct</code> passthrough + classic verbatim dispatch; destructive paths guarded by retype + y/N double confirmation</td></tr><tr><td>TUI</td><td>Desktop, taskbar, menus, forms, editor, system apps - ring-3 programs riding the L1SVC tui service, plus a Chinese console layer (16x16 font, pinyin IME)</td></tr><tr><td>Reliability</td><td>Crash dumps to serial + /etc crashlog, kernel log with rotation + levels + filters, health monitor (CPU/mem/tasks/IO + JSON export), OTA with SHA256 + signatures and rollback</td></tr><tr><td>OCBL</td><td>The in-tree bootloader (<code>ocbl/</code>): BIOS stage 1 (El Torito / MBR) + UEFI entry, the boot menu, the installer target (<code>ocbl-install</code>)</td></tr><tr><td>OCIRE</td><td>The independent recovery kernel (<code>ocire/</code>): a second L0 that shares no code with OCOS, boots standalone from its own ISO, stores its image in an isolated partition OCOS cannot read or write (see <code>docs/dev/ocire.md</code>)</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># build (Linux): needs gcc nasm xorriso mtools grub-common</span></span>
<span class="line"><span>#               grub-pc-bin grub-efi-amd64-bin zip python3</span></span>
<span class="line"><span>tools/build.sh iso</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run it</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512M -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># inside the guest (the default boot entry is the ring-3 ush shell)</span></span>
<span class="line"><span>ush&gt; hwinfo            (wizard: what hardware is this machine?)</span></span>
<span class="line"><span>ush&gt; update            (wizard: network -&gt; A/B -&gt; DNS -&gt; check -&gt; install)</span></span>
<span class="line"><span>ush&gt; help -a           (all 284 registry programs)</span></span>
<span class="line"><span>ush&gt; dhcp</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; lsblk             (or: disk-tool, and pick it from the menu)</span></span></code></pre></div><p>UEFI instead of BIOS: <code>make run-uefi</code>. Windows hosts: <code>build.ps1</code> (WSL2/MSYS2). Full guides: <a href="./BUILDING.html">BUILDING.md</a>.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Two channels ship from the same byte-reproducible pipeline - both are on the <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub releases page</a> and mirrored on the <a href="https://ocos.cubestudio.cn/download.html" target="_blank" rel="noreferrer">website downloads page</a>:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Assets</th></tr></thead><tbody><tr><td><strong>development preview</strong></td><td><code>opencube-&lt;version&gt;.iso</code> (boots OCBL → OCOS → ush)</td></tr><tr><td><strong>2.2.0</strong> (stable, the 2.x line)</td><td><code>opencube-2.2.0.iso</code> · <code>opencube-2.2.0-src.zip</code> (deterministic source) · <code>opencube-2.2.0-update.tar.gz</code> (OTA)</td></tr></tbody></table><p>Each release note carries the SHA256 of every asset; the website, the Release and the private mirror hold byte-identical copies.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><a href="./BUILDING.html">BUILDING.md</a> - build on Linux/Windows, QEMU, cross-compilation (ARM64/RISC-V shells), reproducible verification</li><li><a href="./ARCHITECTURE.html">ARCHITECTURE.md</a> - the L0/L1 architecture, top to bottom</li><li><a href="./INTERFACES.html">INTERFACES.md</a> - the command surface by home and the L1SVC service tables (generated from the tree: <code>make api-docs</code>)</li><li><a href="./FAQ.html">FAQ.md</a> - common questions</li><li><a href="./CONTRIBUTING.html">CONTRIBUTING.md</a> - ground rules and the PR bar</li><li>The full documentation center (user manual with the mega-app guide, developer handbook, driver bring-up guides, internals): <strong><a href="https://ocos.cubestudio.cn/docs/" target="_blank" rel="noreferrer">https://ocos.cubestudio.cn/docs/</a></strong></li></ul><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p>All numbers below are machine-verified at build time (<code>make api-docs</code> writes <code>docs/data/*.json</code>; the README verification command is quoted per item):</p><ul><li><strong>Source code</strong>: 158,474 lines across 764 files - ocos/ (kernel, drivers, services, interface, l1apps) + ocbl/ + ocire/, headers included, generated data blobs excluded (the generator caliber: <code>tools/gen_api_docs.py</code> <code>STAT_DIRS</code>/<code>STAT_EXCLUDE</code>). Verify: <code>python3 tools/gen_api_docs.py &amp;&amp; python3 -c &quot;import json;d=json.load(open(&#39;docs/data/stats.json&#39;));print(sum(v[&#39;lines&#39;] for v in d[&#39;dirs&#39;].values()))&quot;</code></li><li><strong>Commands</strong>: 296 total - 284 ring-3 registry apps (one command = one app = one folder under <code>ocos/l1apps/</code>, the 8 merged mega-apps included) + 12 ush built-ins + 0 in L0. The registry floor is enforced by the regression gate (&gt;= 276).</li><li><strong>L1SVC service surface</strong>: 20 categories / 208 numbered ops - see <a href="./INTERFACES.html">INTERFACES.md</a> for the exact tables.</li><li><strong>Syscalls</strong>: 54 - verify: <code>grep -c &#39;#define SYS_&#39; ocos/services/sysapi/interface/svc_sysapi_syscall.h</code></li><li><strong>CI</strong>: green on every push - build, ISO, packages, host tests and the reproducibility gate (<code>.github/workflows/build.yml</code>).</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Apache 2.0 - see <a href="./LICENSE.html">LICENSE</a>. Every source file carries <code>SPDX-License-Identifier: Apache-2.0</code>.</p><p>Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt;</p>`,24)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
